replace_once(
    "google_health_viewer/agent_runtime_v2.py",
    '''    "energy": (\n        "mi sento energico",\n        "mi sento energica",\n        "pieno di energia",\n        "piena di energia",\n        "i feel energetic",\n        "full of energy",\n    ),\n}\n\n\ndef _detect_self_report(question: str) -> dict[str, str] | None:\n    text = question.strip()\n    folded = text.casefold()\n    for category, markers in _SELF_REPORT_PATTERNS.items():\n        if any(marker in folded for marker in markers):\n            return {"category": category, "statement": text}\n    return None\n''',
    '''    "energy": (\n        "mi sento energico",\n        "mi sento energica",\n        "pieno di energia",\n        "piena di energia",\n        "i feel energetic",\n        "full of energy",\n    ),\n    "sleep_quality": (\n        "non ho dormito bene",\n        "ho dormito male",\n        "ho dormito malissimo",\n        "sonno pessimo",\n        "sonno scarso",\n        "i didn't sleep well",\n        "i did not sleep well",\n        "i slept badly",\n        "poor sleep",\n    ),\n}\n\n\ndef _detect_self_reports(question: str) -> list[dict[str, str]]:\n    text = question.strip()\n    folded = text.casefold()\n    reports: list[dict[str, str]] = []\n    for category, markers in _SELF_REPORT_PATTERNS.items():\n        if any(marker in folded for marker in markers):\n            reports.append({"category": category, "statement": text})\n    return reports[:3]\n\n\ndef _detect_self_report(question: str) -> dict[str, str] | None:\n    reports = _detect_self_reports(question)\n    return reports[0] if reports else None\n\n\ndef _self_report_temporal_context(\n    question: str, *, now: datetime | None = None\n) -> tuple[str | None, dict[str, Any]]:\n    """Resolve explicit day-level relative time without inventing an exact event time."""\n\n    current = now.astimezone() if now is not None else datetime.now().astimezone()\n    folded = question.casefold()\n    offset: int | None = None\n    reference = ""\n    if "ieri" in folded or "yesterday" in folded:\n        offset = -1\n        reference = "yesterday"\n    elif "oggi" in folded or "today" in folded:\n        offset = 0\n        reference = "today"\n    if offset is None:\n        return None, {}\n    local_date = current.date() + timedelta(days=offset)\n    # Noon is a neutral date anchor; temporal_precision tells downstream logic not to\n    # interpret it as the user's claimed event clock time.\n    observed = datetime.combine(local_date, time(12, 0), tzinfo=current.tzinfo)\n    return observed.isoformat(), {\n        "temporal_reference": reference,\n        "observed_local_date": local_date.isoformat(),\n        "temporal_precision": "day",\n    }\n''',
)
replace_once(
    "google_health_viewer/agent_runtime_v2.py",
    '''        detected_self_report = _detect_self_report(request)\n        captured_self_report = None\n        if detected_self_report is not None:\n            captured_self_report = self.agent_store.record_self_report(\n                detected_self_report["statement"],\n                category=detected_self_report["category"],\n                thread_id=thread_id,\n                context={"source": "conversation", "explicit_self_report": True},\n            )\n            event(_("Subjective self-report saved locally as a dated event."))\n            learning_key = f"self_report_detail:{detected_self_report['category']}"\n            if captured_self_report and not self.agent_store.has_recent_feedback_key(\n                learning_key, days=14\n            ):\n                feedback_question, feedback_reason = _self_report_follow_up(\n                    detected_self_report["category"]\n                )\n                queued = self.agent_store.ask_feedback(\n                    feedback_question,\n                    thread_id=thread_id,\n                    reason=feedback_reason,\n                    learning_key=learning_key,\n                    context={\n                        "self_report_id": captured_self_report.get("report_id"),\n                        "category": detected_self_report["category"],\n                        "feedback_mode": "self_report_detail",\n                    },\n                )\n                if queued:\n                    event(_("One targeted follow-up was queued to improve future personalisation."))\n        initial = self._initial_context(snapshot)\n        if captured_self_report:\n            initial["current_self_report"] = captured_self_report\n            initial["self_report_rule"] = (\n                "This was stored as a dated subjective event. Do not promote it to a stable association from one occurrence."\n            )\n''',
    '''        detected_self_reports = _detect_self_reports(request)\n        captured_self_reports: list[dict[str, Any]] = []\n        observed_at, temporal_context = _self_report_temporal_context(request)\n        categories = [item["category"] for item in detected_self_reports]\n        folded_request = request.casefold()\n        shared_context: dict[str, Any] = {\n            "source": "conversation",\n            "explicit_self_report": True,\n            "co_reported_categories": categories,\n            **temporal_context,\n        }\n        if "cardio" in folded_request:\n            shared_context["user_reported_activity_context"] = "cardio"\n            if any(\n                marker in folded_request\n                for marker in ("molta cardio", "molto cardio", "much cardio", "a lot of cardio")\n            ):\n                shared_context["user_reported_activity_load"] = "high"\n        for detected_self_report in detected_self_reports:\n            captured = self.agent_store.record_self_report(\n                detected_self_report["statement"],\n                category=detected_self_report["category"],\n                thread_id=thread_id,\n                observed_at=observed_at,\n                context=shared_context,\n            )\n            if captured:\n                captured_self_reports.append(captured)\n        if captured_self_reports:\n            event(_("Subjective self-report saved locally as a dated event."))\n            primary = captured_self_reports[0]\n            primary_category = str(primary.get("category") or "wellbeing")\n            learning_key = f"self_report_detail:{primary_category}"\n            if not self.agent_store.has_recent_feedback_key(learning_key, days=14):\n                feedback_question, feedback_reason = _self_report_follow_up(primary_category)\n                queued = self.agent_store.ask_feedback(\n                    feedback_question,\n                    thread_id=thread_id,\n                    reason=feedback_reason,\n                    learning_key=learning_key,\n                    context={\n                        "self_report_id": primary.get("report_id"),\n                        "category": primary_category,\n                        "feedback_mode": "self_report_detail",\n                    },\n                )\n                if queued:\n                    event(_("One targeted follow-up was queued to improve future personalisation."))\n        initial = self._initial_context(snapshot)\n        if captured_self_reports:\n            initial["current_self_report"] = captured_self_reports[0]\n            initial["current_self_reports"] = captured_self_reports\n            initial["self_report_rule"] = (\n                "These were stored as dated subjective events. Do not duplicate them with record_self_report "\n                "and do not promote one occurrence to a stable association. Repeated similar reports may "\n                "support a cautious personal association only when the evidence genuinely repeats."\n            )\n''',
)

