    text += '''\n\ndef test_generic_tool_word_does_not_trigger_unsupported_model_fallback():\n    assert (\n        _tool_calling_unavailable_error(\n            "The local model returned neither an answer nor a tool call."\n        )\n        is False\n    )\n    assert _tool_calling_unavailable_error("model does not support tools") is True\n\n\ndef test_empty_agent_turn_is_retried_instead_of_raising(tmp_path):\n    store = AgentStore(tmp_path / "agent.sqlite3")\n\n    class EmptyTurnRuntime(AgentRuntime):\n        def __init__(self, health_store, agent_store):\n            super().__init__(health_store, agent_store)\n            self.turn = 0\n\n        def _chat_once(self, **_kwargs):\n            self.turn += 1\n            if self.turn == 1:\n                return {"content": "", "tool_calls": []}\n            return {"content": "Recovered answer"}\n\n    runtime = EmptyTurnRuntime(DummyHealthStore(tmp_path / "health.sqlite3"), store)\n    events: list[str] = []\n    answer = runtime.analyze(\n        model="test",\n        snapshot={},\n        question="Come sto recuperando?",\n        history=[],\n        max_tokens=1024,\n        model_context_limit=None,\n        performance_profile="standard",\n        thread_id="empty-turn",\n        event_callback=events.append,\n    )\n    assert answer == "Recovered answer"\n    assert runtime.turn == 2\n    assert any("empty turn" in item.lower() for item in events)\n'''
